css:
/* ==== INTERFACE ====
方向：Bento Grid (便当盒模块化布局)；以清晰的圆角几何切分、克制的局部中性面、精细对齐与等宽间距，支撑神经网络架构图、前向/反向传播公式分步、损失曲面与二维决策边界的对照推导；排版采用几何无衬线与清晰黑体。
reference style:05-bento-grid
token --bg: 页面底色 (#f4f6f9)。
token --text: 正文墨色 (#141923)。
token --font-sans: 正文与交互字体 ("NTF-inter", "NTF-noto-sans-sc", sans-serif)。
token --font-title: 标题字体栈 ("NTF-space-grotesk", "NTF-noto-sans-sc", sans-serif)。
class .nt-title: 普通页题名，字阶 36px/1.25，字重 700，带微字距与几何标题质感；英文优先 Space Grotesk，中文承接 Noto Sans SC。
class .nt-h2: 模块与区块标题，字阶 20px/1.35，字重 600。
class .nt-lead: 导读与论点段落，字阶 18px/1.5，浅墨色。
class .nt-bento-cell: 便当盒基础单元格外壳，提供 16px 圆角、微细边界线条与柔和漫反射环境阴影，内部弹性填充。
class .nt-bento-cell--accent: 核心高亮视窗单元格（如决策边界主画板或损失下降曲线），微淡青蓝底。
class .nt-tag: 状态与流程标签（如 "Forward"、"Backward"、"Layer 1"），字阶 13px，圆角胶囊。
class .nt-btn: 通用交互按钮，支持 hover、active 与 aria-pressed="true" 激活态。
class .nt-math-block: 公式与推导呈现块，等宽数学环境承接。
class .nt-node, .nt-edge: 神经网络计算图中的节点与连接线，支持通过 CSS 变量 --flow-color / --node-val 注入激活程度。
variant opening: 封面开篇，更充裕的留白、放大的标题字阶 (52px) 与居中对齐网格结构。
默认：不设 data-variant；无图时保持 #f4f6f9 微细网格底，不依赖外部位图。
品牌：无。
==== /INTERFACE ==== */

@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-space-grotesk";
  src: url("fonts/library/space-grotesk/face-0.ttf");
  font-weight: 300 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

:root {
  /* 基础底色与文字墨色 */
  --bg: #f4f6f9;
  --text: #141923;
  --text-secondary: #586274;
  --text-muted: #8b95a5;
  --border: rgba(20, 25, 35, 0.08);
  --border-focus: #2563eb;
  --focus: rgba(37, 99, 235, 0.4);

  /* 便当盒模块背景与阴影 */
  --cell-bg: #ffffff;
  --cell-bg-subtle: #f8fafc;
  --cell-bg-accent: #eff6ff;
  --cell-shadow: 0 4px 16px -2px rgba(15, 23, 42, 0.04), 0 1px 3px 0 rgba(15, 23, 42, 0.02);
  --cell-shadow-lift: 0 10px 24px -4px rgba(15, 23, 42, 0.08), 0 2px 6px 0 rgba(15, 23, 42, 0.03);

  /* 字体族 */
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-title: "NTF-space-grotesk", "NTF-noto-sans-sc", sans-serif;
  --font-mono: ui-monospace, "Cascadia Code", "Source Code Pro", Menlo, Consolas, monospace;

  /* 字阶规范 (固定画布设计 px) */
  --fs-hero: 52px;
  --fs-h1: 34px;
  --fs-h2: 20px;
  --fs-h3: 17px;
  --fs-lead: 18px;
  --fs-body: 15px;
  --fs-sec: 14px;
  --fs-label: 13px;
  --fs-tick: 12px;

  /* 几何与间距 */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-pill: 9999px;

  /* 科学图解色盘（用于分类散点、网络正负权重、流向） */
  --nn-cyan: #0284c7;
  --nn-indigo: #4f46e5;
  --nn-amber: #d97706;
  --nn-rose: #e11d48;
  --nn-emerald: #059669;
}

/* 舞台容器 */
#stage {
  background-color: var(--bg);
  background-image: 
    radial-gradient(var(--border) 1px, transparent 1px);
  background-size: 24px 24px;
  background-position: 0 0;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.55;
  box-sizing: border-box;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 变体：开篇封面 */
html[data-variant="opening"] #stage {
  background-color: #f0f4f8;
  background-image: 
    radial-gradient(circle at 85% 15%, rgba(79, 70, 229, 0.06) 0%, transparent 40%),
    radial-gradient(circle at 15% 85%, rgba(2, 132, 199, 0.06) 0%, transparent 45%),
    radial-gradient(var(--border) 1.2px, transparent 1.2px);
  background-size: 100% 100%, 100% 100%, 28px 28px;
}

/* 标题系统 */
.nt-title {
  font-family: var(--font-title);
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  color: var(--text);
  margin: 0;
}

html[data-variant="opening"] .nt-title {
  font-size: var(--fs-hero);
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.nt-h2 {
  font-family: var(--font-title);
  font-size: var(--fs-h2);
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: -0.01em;
  color: var(--text);
  margin: 0 0 8px 0;
}

.nt-h3 {
  font-family: var(--font-title);
  font-size: var(--fs-h3);
  font-weight: 600;
  line-height: 1.4;
  color: var(--text);
  margin: 0 0 6px 0;
}

.nt-lead {
  font-size: var(--fs-lead);
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 0;
}

.nt-body {
  font-size: var(--fs-body);
  line-height: 1.55;
  color: var(--text);
}

.nt-sec {
  font-size: var(--fs-sec);
  line-height: 1.5;
  color: var(--text-secondary);
}

.nt-label {
  font-size: var(--fs-label);
  font-weight: 500;
  line-height: 1.3;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* 便当盒模块化外壳 */
.nt-bento-cell {
  background: var(--cell-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--cell-shadow);
  padding: 20px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

.nt-bento-cell--subtle {
  background: var(--cell-bg-subtle);
}

.nt-bento-cell--accent {
  background: var(--cell-bg-accent);
  border-color: rgba(37, 99, 235, 0.2);
}

.nt-bento-cell--interactive:hover {
  box-shadow: var(--cell-shadow-lift);
  border-color: rgba(37, 99, 235, 0.35);
}

/* 标签与指示徽章 */
.nt-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  background: #f1f5f9;
  border: 1px solid rgba(15, 23, 42, 0.06);
  font-size: var(--fs-label);
  font-weight: 600;
  color: var(--text-secondary);
  letter-spacing: 0.01em;
}

.nt-tag--forward {
  background: #eff6ff;
  border-color: #bfdbfe;
  color: #1d4ed8;
}

.nt-tag--backward {
  background: #fef2f2;
  border-color: #fecaca;
  color: #b91c1c;
}

.nt-tag--loss {
  background: #fffbeb;
  border-color: #fde68a;
  color: #b45309;
}

/* 交互按钮与控制器 */
.nt-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  background: var(--text);
  color: #ffffff;
  border: 1px solid transparent;
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 500;
  cursor: pointer;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
  transition: all 0.15s ease;
  user-select: none;
}

.nt-btn:hover {
  background: #2b3547;
}

.nt-btn:active {
  transform: translateY(1px);
}

.nt-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.nt-btn--secondary {
  background: #ffffff;
  color: var(--text);
  border-color: var(--border);
}

.nt-btn--secondary:hover {
  background: #f8fafc;
  border-color: rgba(20, 25, 35, 0.18);
}

.nt-btn[aria-pressed="true"] {
  background: var(--nn-indigo);
  color: #ffffff;
  border-color: transparent;
}

/* 神经网络数学推导块与代码 */
.nt-math-block {
  font-family: var(--font-mono);
  background: #f8fafc;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 12px 16px;
  font-size: var(--fs-sec);
  line-height: 1.6;
  color: #1e293b;
  overflow-x: auto;
}

/* 神经网络计算图中的节点与连线共享样式 */
.nt-graph-node {
  fill: #ffffff;
  stroke: var(--nn-indigo);
  stroke-width: 2.5px;
  transition: all 0.2s ease;
}

.nt-graph-node--active {
  fill: #e0e7ff;
  stroke: var(--nn-indigo);
  stroke-width: 3px;
}

.nt-graph-node--target {
  stroke: var(--nn-rose);
}

.nt-graph-edge {
  fill: none;
  stroke: #cbd5e1;
  stroke-width: 2px;
  stroke-linecap: round;
  transition: stroke 0.2s ease, stroke-width 0.2s ease;
}

.nt-graph-edge--forward {
  stroke: var(--nn-indigo);
  stroke-width: 2.5px;
}

.nt-graph-edge--backward {
  stroke: var(--nn-rose);
  stroke-width: 2.5px;
  stroke-dasharray: 4 3;
}

.nt-graph-text {
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  fill: var(--text);
  text-anchor: middle;
  dominant-baseline: central;
  font-weight: 500;
}

/* 决策边界图例与散点规范类 */
.nt-point-class0 {
  fill: var(--nn-cyan);
  stroke: #ffffff;
  stroke-width: 1.5px;
}

.nt-point-class1 {
  fill: var(--nn-amber);
  stroke: #ffffff;
  stroke-width: 1.5px;
}

/* 减少动态偏好 */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
